package kz.printlab.dto; import jakarta.validation.constraints.*;
public class ProfileUpdateRequest { @Size(max=120,message="Не более 120 символов") private String fullName; @Size(max=100,message="Не более 100 символов") private String city; @Size(max=30,message="Не более 30 символов") private String phone; @Size(max=2000,message="Не более 2000 символов") private String deliveryAddress;
 public String getFullName(){return fullName;} public void setFullName(String v){fullName=v;} public String getCity(){return city;} public void setCity(String v){city=v;} public String getPhone(){return phone;} public void setPhone(String v){phone=v;} public String getDeliveryAddress(){return deliveryAddress;} public void setDeliveryAddress(String v){deliveryAddress=v;}}
